<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();
function aplicar_compra(PDO $pdo,int $id):void{$st=$pdo->prepare('SELECT * FROM compras WHERE id=?');$st->execute([$id]);$c=$st->fetch();if(!$c||$c['inventario_aplicado']||$c['estatus']!=='Recibido')return;$it=$pdo->prepare('SELECT * FROM compra_items WHERE compra_id=? AND inventario_id IS NOT NULL');$it->execute([$id]);foreach($it as $r){$pdo->prepare('UPDATE inventario SET stock=stock+?,costo_unitario=? WHERE id=?')->execute([$r['cantidad'],$r['costo_unitario'],$r['inventario_id']]);$pdo->prepare("INSERT INTO movimientos_inventario(inventario_id,tipo,cantidad,costo_unitario,referencia_tipo,referencia_id,notas) VALUES(?, 'Compra recibida', ?, ?, 'Compra', ?, ?)")->execute([$r['inventario_id'],$r['cantidad'],$r['costo_unitario'],$id,$c['numero_pedido']]);}$pdo->prepare('UPDATE compras SET inventario_aplicado=1 WHERE id=?')->execute([$id]);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['guardar'])){$pdo->beginTransaction();try{$prov=(int)($_POST['proveedor_id']??0);$cot=(int)($_POST['cotizacion_id']??0);$fecha=epost('fecha',date('Y-m-d'));$estatus=epost('estatus','Solicitado');$pdo->prepare('INSERT INTO compras(proveedor_id,cotizacion_id,fecha,numero_pedido,tracking,estatus,total,fecha_estimada,notas) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$prov?:null,$cot?:null,$fecha,epost('numero_pedido'),epost('tracking'),$estatus,0,epost('fecha_estimada')?:null,epost('notas')]);$id=(int)$pdo->lastInsertId();$desc=$_POST['descripcion']??[];$inv=$_POST['inventario_id']??[];$cant=$_POST['cantidad']??[];$cost=$_POST['costo_unitario']??[];$total=0;$ins=$pdo->prepare('INSERT INTO compra_items(compra_id,inventario_id,descripcion,cantidad,costo_unitario,total) VALUES(?,?,?,?,?,?)');for($i=0;$i<count($desc);$i++){$d=trim((string)$desc[$i]);$q=max(0,(float)($cant[$i]??0));$cu=max(0,(float)($cost[$i]??0));if($d!==''&&$q>0){$t=round($q*$cu,2);$total+=$t;$iid=(int)($inv[$i]??0);$ins->execute([$id,$iid?:null,$d,$q,$cu,$t]);}}$pdo->prepare('UPDATE compras SET total=? WHERE id=?')->execute([$total,$id]);$pdo->commit();aplicar_compra($pdo,$id);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 if(isset($_POST['estado'])){$id=(int)$_POST['id'];$pdo->prepare('UPDATE compras SET estatus=?,tracking=?,fecha_estimada=? WHERE id=?')->execute([epost('estatus'),epost('tracking'),epost('fecha_estimada')?:null,$id]);aplicar_compra($pdo,$id);}
 ego('compras.php');
}
$prefCot=(int)($_GET['cotizacion_id']??0);$provs=$pdo->query('SELECT * FROM proveedores WHERE activo=1 ORDER BY nombre')->fetchAll();$cots=srnu_get_cotizaciones_select();$inv=$pdo->query('SELECT * FROM inventario WHERE activo=1 ORDER BY nombre')->fetchAll();$rows=$pdo->query("SELECT c.*,p.nombre proveedor,co.folio,co.cliente,co.vehiculo,(SELECT COUNT(*) FROM compra_items ci WHERE ci.compra_id=c.id) items FROM compras c LEFT JOIN proveedores p ON p.id=c.proveedor_id LEFT JOIN cotizaciones co ON co.id=c.cotizacion_id ORDER BY c.id DESC LIMIT 400")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compras · SRNU</title><?=srnu_ui_head()?><style>.purchase-row{display:grid;grid-template-columns:1fr 1.6fr .6fr .8fr auto;gap:8px;margin-top:8px}@media(max-width:700px){.purchase-row{grid-template-columns:1fr}}</style></head><body><?php srnu_appbar('compras');?><main class="w"><div class="srnu-page-heading"><div><h1>Compras y pedidos</h1><p>Pedidos a proveedores, tracking, productos sobre pedido y entradas a inventario.</p></div><div class="toolbar"><a class="btn light" href="proveedores.php">Proveedores</a><a class="btn light" href="inventario.php">Inventario</a></div></div><section class="panel" style="padding:18px"><h3>Nueva compra / pedido</h3><form method="post"><div class="erp-form cols-4"><select name="proveedor_id"><option value="">Proveedor</option><?php foreach($provs as $p):?><option value="<?=$p['id']?>"><?=eh($p['nombre'])?></option><?php endforeach;?></select><select name="cotizacion_id"><option value="">Sin cotización</option><?php foreach($cots as $c):?><option value="<?=$c['id']?>" <?=$prefCot===(int)$c['id']?'selected':''?>><?=eh(srnu_cotizacion_label($c))?></option><?php endforeach;?></select><input type="date" name="fecha" value="<?=date('Y-m-d')?>"><select name="estatus"><option>Solicitado</option><option>Pagado</option><option>En tránsito</option><option>Recibido</option><option>Cancelado</option></select><input name="numero_pedido" placeholder="No. pedido"><input name="tracking" placeholder="Tracking"><input type="date" name="fecha_estimada"><input name="notas" placeholder="Notas"></div><div id="purchase-items"><div class="purchase-row"><select name="inventario_id[]"><option value="">No ligar a inventario</option><?php foreach($inv as $i):?><option value="<?=$i['id']?>"><?=eh($i['nombre'])?></option><?php endforeach;?></select><input name="descripcion[]" placeholder="Producto / concepto"><input type="number" step="0.001" min="0" name="cantidad[]" value="1"><input type="number" step="0.01" min="0" name="costo_unitario[]" placeholder="Costo unitario"><button type="button" class="btn light" onclick="this.parentElement.remove()">×</button></div></div><div class="toolbar" style="margin-top:10px"><button type="button" class="btn light" onclick="addPurchaseRow()">+ Línea</button><button class="btn blue" name="guardar" value="1">Guardar compra</button></div></form></section><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Pedido</th><th>Proveedor / cotización</th><th>Estado</th><th>Tracking / estimada</th><th>Total</th><th>Actualizar</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=eh($r['numero_pedido']?:'#'.$r['id'])?></b><div class="muted"><?=edate($r['fecha'])?> · <?=$r['items']?> línea(s)</div></td><td><?=eh($r['proveedor'])?><div class="muted"><?=eh(trim(($r['folio']??'').' '.($r['cliente']??'').' '.($r['vehiculo']??'')))?></div></td><td><span class="badge <?=$r['estatus']==='Recibido'?'badge-green':($r['estatus']==='Cancelado'?'badge-red':'badge-orange')?>"><?=eh($r['estatus'])?></span><?php if($r['inventario_aplicado']):?><div class="muted">✓ Inventario aplicado</div><?php endif;?></td><td><?=eh($r['tracking'])?><div class="muted">Estimada <?=edate($r['fecha_estimada'])?></div></td><td><?=emoney($r['total'])?></td><td><form method="post" class="toolbar"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="estatus"><option <?=$r['estatus']==='Solicitado'?'selected':''?>>Solicitado</option><option <?=$r['estatus']==='Pagado'?'selected':''?>>Pagado</option><option <?=$r['estatus']==='En tránsito'?'selected':''?>>En tránsito</option><option <?=$r['estatus']==='Recibido'?'selected':''?>>Recibido</option><option <?=$r['estatus']==='Cancelado'?'selected':''?>>Cancelado</option></select><input name="tracking" value="<?=eh($r['tracking'])?>" placeholder="Tracking"><input type="date" name="fecha_estimada" value="<?=eh($r['fecha_estimada'])?>"><button class="btn" name="estado" value="1">Guardar</button></form></td></tr><?php endforeach;?></tbody></table></section></main><template id="prow"><div class="purchase-row"><select name="inventario_id[]"><option value="">No ligar a inventario</option><?php foreach($inv as $i):?><option value="<?=$i['id']?>"><?=eh($i['nombre'])?></option><?php endforeach;?></select><input name="descripcion[]" placeholder="Producto / concepto"><input type="number" step="0.001" min="0" name="cantidad[]" value="1"><input type="number" step="0.01" min="0" name="costo_unitario[]" placeholder="Costo unitario"><button type="button" class="btn light" onclick="this.parentElement.remove()">×</button></div></template><script>function addPurchaseRow(){document.getElementById('purchase-items').append(document.getElementById('prow').content.cloneNode(true))}</script></body></html>
